import pandas as pd

value_2008 = None
value_total = None

for _, row in df.iterrows():
    row_vals = row.values
    for i, cell in enumerate(row_vals):
        if isinstance(cell, str):
            if '2008' in cell:
                other = row_vals[1 - i] if len(row_vals) > 1 else None
                if pd.notnull(other):
                    value_2008 = float(other)
            if 'total future minimum sponsorship and other marketing payments' in cell.lower():
                other = row_vals[1 - i] if len(row_vals) > 1 else None
                if pd.notnull(other):
                    value_total = float(other)

result = value_2008 / value_total if value_2008 is not None and value_total else None
